Translate the following Java 11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class TwentyFive {
    public static void main(String[] args) throws Exception {
        new BufferedReader(new InputStreamReader(System.in));
        String input = System.console() != null ? System.console().readLine() : new Scanner(System.in).nextLine();
        String s = input == null ? "" : input.trim();

        int solutions = 0;
        for (int i = 0; i < 100_000_000; i += 25) {
            String t = String.valueOf(i);
            if (t.length() != s.length()) continue;

            boolean ok = true;
            char foundX = 0;
            boolean firstX = true;

            for (int k = 0; k < s.length(); k++) {
                char sc = s.charAt(k);
                char tc = t.charAt(k);

                if (sc == 'X') {
                    if (firstX) {
                        foundX = tc;
                        firstX = false;
                    } else if (tc != foundX) {
                        ok = false;
                        break;
                    }
                } else if (sc != '_') {
                    if (tc != sc) {
                        ok = false;
                        break;
                    }
                }
            }

            if (ok) solutions++;
        }

        System.out.println(solutions);
    }
}
